from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
import re, os
out='/root/output/result.xlsx'
wb=load_workbook(out, data_only=False)
ws=wb['Task']

print('=== Verification formulas requested ===')
for addr in ['H12','H19','H26','H35','H40','H42','H43','H44','H45','H46','H47','H50']:
    print(f'{addr}: {ws[addr].value!r}')

expected_ranges=[]
for rs,re_ in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(rs,re_+1):
        for c in range(8,13):
            expected_ranges.append((r,c))

bad=[]
for r,c in expected_ranges:
    v=ws.cell(r,c).value
    addr=f'{get_column_letter(c)}{r}'
    if v is None or v == '' or (isinstance(v,str) and '#NAME?' in v):
        bad.append((addr,v))
    elif not (isinstance(v,str) and v.startswith('=')):
        bad.append((addr, f'not formula: {v!r}'))

formulas=[ws.cell(r,c).value for r,c in expected_ranges if isinstance(ws.cell(r,c).value,str)]
functions=set()
for f in formulas:
    for m in re.finditer(r'([A-Z][A-Z\.]*?)\s*\(', f.upper()):
        functions.add(m.group(1))
allowed={'INDEX','MATCH','MIN','MAX','MEDIAN','AVERAGE','PERCENTILE','SUMPRODUCT','SUM'}
disallowed=sorted(functions-allowed)

print('\nExpected formula cell count:', len(expected_ranges))
print('Missing/empty/#NAME?/non-formula issues:', bad if bad else 'None')
print('Functions found:', sorted(functions))
print('Disallowed functions:', disallowed if disallowed else 'None')
print('Uses dotted percentile variants:', any('PERCENTILE.' in f.upper() for f in formulas))
print('File size bytes:', os.path.getsize(out))

if bad or disallowed or any('PERCENTILE.' in f.upper() for f in formulas):
    raise SystemExit(1)
print('\nVERIFY_OK')
